properties.query:
let iot_events = SecurityEvent | where Computer startswith "iot-" or ProcessName has_any ("firmware", "sensor", "gateway") and EventID == 4624 | summarize iot_time=min(TimeGenerated) by Computer;
let pivot_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize pivot_time=min(TimeGenerated) by TargetUserName, Computer;
iot_events | join kind=inner pivot_events on Computer | where pivot_time - iot_time between (0min .. 120min)
